bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(docker inspect -f '{{.State.Running}}' deploy-gaybbs-1)" = true
docker exec deploy-gaybbs-1 sha256sum /app/gaybbs.mjs
docker logs --since 60m --tail 3000 deploy-gaybbs-1 2>&1 | python3 -c 'import sys,re,collections
s=sys.stdin.read()
codes=collections.Counter(re.findall(r"reason:\s*[\x27\x22]([A-Z][A-Z0-9_]{3,100})[\x27\x22]",s))
for k,v in sorted(codes.items()): print("ERROR_CODE",k,v)
for k in ["POST_PUBLICATION_FAILED","FEATURE_RELEASE_NOT_VERIFIED","APPLICATION_SOURCE_NOT_OWNED","NOTICE_SOURCE_NOT_OWNED","PUBLISH_NEEDS_RECONCILE","POST_SENT_SOURCE_SYNC_NEEDS_RECONCILE","NOTICE_EDITOR_ERROR_EDIT_FAILED","Bad Request","Forbidden"]: print("LOG_COUNT",k,s.count(k))'
docker exec deploy-postgres-1 psql -X -v ON_ERROR_STOP=1 -U gace -d gaybbs -Atqc "
SELECT 'notice_release',enabled,length(source_commit)=40,length(trim(ci_evidence))>0,length(trim(gserver_runtime_evidence))>0,length(trim(telegram_e2e_evidence))>0,approved_by IS NOT NULL FROM gaybbs_feature_release_gates WHERE feature='announcement';
SELECT 'notice_drafts',step,count(*) FROM public_post_drafts WHERE module='announcement' AND data->>'kind' IN ('announcement','preview') GROUP BY step;
SELECT 'notice_sources',p.status,count(*) FROM announcement_posts p WHERE kind IN ('announcement','preview') GROUP BY p.status;
SELECT 'notice_delivery',d.status,count(*) FROM posting_deliveries d JOIN announcement_posts p ON p.announcement_id::text=d.source_id WHERE d.source_type='announcement' AND p.kind IN ('announcement','preview') GROUP BY d.status;
"
